public class SelfComposeTest {
    static int failures = 0;

    static void check(String label, Object expected, Object actual) {
        if (java.util.Objects.equals(expected, actual)) {
            System.out.println("PASS  " + label);
        } else {
            System.out.println("FAIL  " + label + " -- expected " + expected + " but got " + actual);
            failures++;
        }
    }

    static Object applyTwice(java.util.function.UnaryOperator<Integer> f, int x) {
        try {
            java.util.function.UnaryOperator<Integer> doubled = SelfCompose.twice(f);
            if (doubled == null) return "null operator";
            return doubled.apply(x);
        } catch (Exception e) {
            return "threw " + e.getClass().getSimpleName();
        }
    }

    public static void main(String[] args) {
        java.util.function.UnaryOperator<Integer> increment = x -> x + 1;
        java.util.function.UnaryOperator<Integer> doubler = x -> x * 2;

        check("increment twice: 5 -> 7", 7, applyTwice(increment, 5));
        check("double twice: 3 -> 12", 12, applyTwice(doubler, 3));
        check("square twice: 2 -> 16", 16, applyTwice(x -> x * x, 2));
        check("subtract 3 twice: 10 -> 4", 4, applyTwice(x -> x - 3, 10));
        check("negate twice is identity: 9 -> 9", 9, applyTwice(x -> -x, 9));
        try {
            java.util.function.UnaryOperator<Integer> reusable = SelfCompose.twice(increment);
            if (reusable == null) {
                check("returned operator is reusable", "[2, 12]", "null operator");
            } else {
                java.util.List<Integer> results = new java.util.ArrayList<>();
                results.add(reusable.apply(0));
                results.add(reusable.apply(10));
                check("returned operator is reusable", "[2, 12]", results.toString());
            }
        } catch (Exception e) {
            check("returned operator is reusable", "[2, 12]",
                    "threw " + e.getClass().getSimpleName());
        }
        if (failures > 0) {
            System.out.println(failures + " test(s) failed.");
            System.exit(1);
        }
        System.out.println("ALL TESTS PASSED");
    }
}

